const solve = (s) => {
  const hasLetter = s.split('').some(c => /[a-zA-Z]/.test(c));
  if (!hasLetter) {
    return s.split('').reverse().join('');
  }
  return s.split('').map(c => {
    if (/[a-z]/.test(c)) return c.toUpperCase();
    if (/[A-Z]/.test(c)) return c.toLowerCase();
    return c;
  }).join('');
};
